371	    /**
372	     * Number of leading hex characters of the identity hash retained as the {@code HASH8} segment of
373	     * the {@code customerCode}.
374	     */
375	    private static final int CUSTOMER_CODE_HASH_LENGTH = 8;
376	
377	    /**
378	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
379	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the owner's canonical region code resolved from
380	     * its {@code postcode} (falling back to its {@code city}) through the shared
381	     * {@link Region#code(String, String)}, and {@code HASH8} is the first 8 upper-case hex characters
382	     * of the SHA-256 digest of the owner's normalized telephone followed by its last name
383	     * (e.g. {@code 'NSW-1A2B3C4D'}). When this base code collides with an existing owner's
384	     * {@code customerCode}, {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that
385	     * makes the result unique (e.g. {@code 'NSW-1A2B3C4D-2'}), so distinct owners always receive
386	     * distinct customer codes.
387	     *
388	     * @param owner the owner being created, with its telephone already normalized
389	     * @return the formatted, de-duplicated customer code
390	     */
391	    private String customerCode(Owner owner) {
392	        String region = Region.code(owner.getPostcode(), owner.getCity());
393	        String hash8 = hashPrefix(owner.getTelephone() + owner.getLastName(), CUSTOMER_CODE_HASH_LENGTH);
394	        String base = region + "-" + hash8;
395	        return deduplicateCustomerCode(base);
396	    }
397	
398	    /**
399	     * Ensures the given base {@code customerCode} does not collide with an existing owner's
400	     * {@code customerCode}. When no existing owner carries the base code it is returned unchanged;
401	     * otherwise {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that yields a code
402	     * held by no existing owner.
403	     *
404	     * @param base the computed base customer code, formatted {@code '<REGION>-<HASH8>'}
405	     * @return the base code, or a {@code '<base>-<n>'} variant that is unique among existing owners
406	     */
407	    private String deduplicateCustomerCode(String base) {
408	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
409	            .map(Owner::getCustomerCode)
410	            .filter(java.util.Objects::nonNull)
411	            .collect(java.util.stream.Collectors.toSet());
412	        if (!existing.contains(base)) {
413	            return base;
414	        }
415	        int n = 2;
416	        while (existing.contains(base + "-" + n)) {
417	            n++;
418	        }
419	        return base + "-" + n;
420	    }
