422	    /**
423	     * Counts how many existing owners already share the given {@code firstName} and {@code lastName},
424	     * compared case-insensitively (using {@link java.util.Locale#ROOT}-independent
425	     * {@link String#equalsIgnoreCase(String)}). The count reflects the owners present before the
426	     * current create, so a name that is unique on create yields {@code 0}. The value is stored on the
427	     * new owner and surfaced as the read-only {@code namesakeCount} field.
428	     *
429	     * @param firstName the first name of the owner being created
430	     * @param lastName the last name of the owner being created
431	     * @return the number of existing owners with the same first and last name (case-insensitive)
432	     */
433	    private int namesakeCount(String firstName, String lastName) {
434	        return (int) countOwners(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
435	            && equalsIgnoreCase(owner.getLastName(), lastName));
