477	    /**
478	     * The maximum number of owners that may be registered on a single day. Once this many owners
479	     * already carry a given {@code registrationDate}, further owners for that date are rejected by
480	     * {@link #rejectDailyRegistrationLimit(LocalDate)}.
481	     */
482	    private static final long MAX_OWNERS_PER_DAY = 100L;
