484	    /**
485	     * Resolves the effective registration date for a create request: the value supplied in the
486	     * request when present, otherwise the server's current date. The result is the raw effective
487	     * date before the business-day adjustment applied by {@link #businessDay(LocalDate)}.
488	     *
489	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
490	     * @return the supplied date, or today when none was supplied
491	     */
492	    private LocalDate effectiveRegistrationDate(LocalDate suppliedDate) {
493	        return suppliedDate != null ? suppliedDate : LocalDate.now();
494	    }
495	
496	    /**
497	     * Rejects a create request whose supplied {@code registrationDate} lies after the server's
498	     * current date. A registration date may be supplied to backdate a create - and is defaulted to
499	     * today when omitted - but it may never be in the future. The check is applied to the raw
500	     * supplied value before the business-day adjustment ({@link #businessDay(LocalDate)}), so a
501	     * future date is rejected regardless of how that adjustment would move it. A future date is
502	     * reported through a {@link FutureRegistrationDateException}, which the
503	     * {@code ExceptionControllerAdvice} renders as a 400 Bad Request response naming the
504	     * {@code registrationDate} field.
505	     *
506	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
507	     * @throws FutureRegistrationDateException if the supplied date is later than the server date
508	     */
509	    private void rejectFutureRegistrationDate(LocalDate suppliedDate) {
510	        if (suppliedDate != null && suppliedDate.isAfter(LocalDate.now())) {
511	            throw new FutureRegistrationDateException(suppliedDate);
512	        }
513	    }
