515	    /**
516	     * Adjusts a date so it falls on a business day. A Saturday is rolled forward to the following
517	     * Monday and a Sunday to the next day (Monday); any weekday is returned unchanged. Applied to
518	     * the effective registration date so that a weekend value - whether supplied in the request or
519	     * defaulted to the server date - is stored as the next Monday, and every value derived from the
520	     * registration date (such as the membership number's year segment and the daily create-limit
521	     * bucket) uses the adjusted business day.
522	     *
523	     * @param date the effective registration date
524	     * @return the same date when it is a weekday, otherwise the next Monday
525	     */
526	    private LocalDate businessDay(LocalDate date) {
527	        DayOfWeek dayOfWeek = date.getDayOfWeek();
528	        if (dayOfWeek == DayOfWeek.SATURDAY) {
529	            return date.plusDays(2);
530	        }
531	        if (dayOfWeek == DayOfWeek.SUNDAY) {
532	            return date.plusDays(1);
533	        }
534	        return date;
535	    }
