537	    /**
538	     * Rejects a create request once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
539	     * created on the given day, counted by {@code registrationDate}. A day at capacity is reported
540	     * through a {@link DailyOwnerRegistrationLimitException}, which the {@code ExceptionControllerAdvice}
541	     * renders as a 429 Too Many Requests response.
542	     *
543	     * @param date the registration date of the owner being created (today)
544	     * @throws DailyOwnerRegistrationLimitException if the day already holds the maximum number of owners
545	     */
546	    private void rejectDailyRegistrationLimit(LocalDate date) {
547	        if (ownersRegisteredOn(date) >= MAX_OWNERS_PER_DAY) {
548	            throw new DailyOwnerRegistrationLimitException(date);
549	        }
550	    }
