552	    /**
553	     * Counts the existing owners whose {@code registrationDate} equals the given day. Shared by the
554	     * hard daily create limit ({@link #rejectDailyRegistrationLimit(LocalDate)}) and the soft
555	     * {@code bulkSignupWarning} flag ({@link #bulkSignupWarning(LocalDate)}) so both accumulate a
556	     * day's owners identically.
557	     *
558	     * @param date the registration date to count owners for
559	     * @return the number of existing owners registered on that day
560	     */
561	    private long ownersRegisteredOn(LocalDate date) {
562	        return countOwners(owner -> date.equals(owner.getRegistrationDate()));
563	    }
