565	    /**
566	     * The soft daily create threshold above which the read-only {@code bulkSignupWarning} flag is
567	     * raised. Once more than this many owners share a {@code registrationDate}, that day is flagged
568	     * as unusually high volume - a warning well below the hard {@link #MAX_OWNERS_PER_DAY} cap.
569	     */
570	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
571	
572	    /**
573	     * Derives the read-only {@code bulkSignupWarning} flag for an owner: {@code true} when more than
574	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have been created (counted by
575	     * {@code registrationDate}) on the given day, otherwise {@code false}. Uses the same per-day
576	     * accumulation as {@link #rejectDailyRegistrationLimit(LocalDate)}. A {@code null} date (an owner
577	     * without a registration date, such as seed data) is never flagged.
578	     *
579	     * @param date the owner's registration date (the day it was created), or {@code null}
580	     * @return {@code true} if the day already holds more than the warning threshold of owners
581	     */
582	    private boolean bulkSignupWarning(LocalDate date) {
583	        if (date == null) {
584	            return false;
585	        }
586	        return ownersRegisteredOn(date) > BULK_SIGNUP_WARNING_THRESHOLD;
587	    }
