589	    /**
590	     * Rejects a create request whose derived {@code identityKey} exactly equals an existing owner's.
591	     * The identity key consolidates the former separate telephone, email and household duplicate
592	     * checks into a single value: {@code normalizedTelephone + '|' + (email or empty) + '|' +
593	     * (householdId or empty)} (see {@link #identityKey(Owner)}). Because the telephone is part of the
594	     * key, two members of the same household (same {@code householdId}) with different telephones have
595	     * different identity keys and are both allowed; only an exact full-key match is a duplicate. A
596	     * collision is reported through a {@link DuplicateOwnerIdentityException}, which the
597	     * {@code ExceptionControllerAdvice} renders as a 409 Conflict response.
598	     *
599	     * @param owner the fully-populated owner being created (telephone, email and household id set)
600	     * @throws DuplicateOwnerIdentityException if an existing owner has the same identity key
601	     */
602	    private void rejectDuplicateIdentity(Owner owner) {
603	        String key = identityKey(owner);
604	        boolean duplicate = existingOwnerMatches(this::identityKey, key);
605	        if (duplicate) {
606	            throw new DuplicateOwnerIdentityException(key);
607	        }
608	    }
