610	    /**
611	     * Rejects a create request that would join an existing household unless it declares the shared
612	     * household with {@code sharesHousehold}. The household is keyed on {@code (lastName, postcode)}
613	     * through the deterministic {@link #householdId(Owner)}, so any existing owner with the same last
614	     * name and postcode is a member of the same household. A second such owner is a household
615	     * duplicate and is rejected with a 409 (via {@link DuplicateOwnerIdentityException}); setting
616	     * {@code sharesHousehold} bypasses this block, so the owner is created as a declared household
617	     * member instead. Owners without a {@code householdId} (e.g. no postcode) have no household to
618	     * collide with and are always allowed.
619	     *
620	     * @param owner the fully-populated owner being created (household id set)
621	     * @param sharesHousehold whether the request declared it shares an existing household
622	     * @throws DuplicateOwnerIdentityException if the household already exists and was not declared
623	     */
624	    private void rejectHouseholdDuplicate(Owner owner, boolean sharesHousehold) {
625	        if (sharesHousehold) {
626	            return;
627	        }
628	        String household = owner.getHouseholdId();
629	        if (household == null) {
630	            return;
631	        }
632	        if (existingOwnerMatches(this::householdId, household)) {
633	            throw new DuplicateOwnerIdentityException(identityKey(owner));
634	        }
635	    }
