637	    /**
638	     * Computes the soft-match {@code possibleDuplicateOf} for a newly created owner: the id of the
639	     * first existing owner that shares this owner's {@code lastName} (compared case-insensitively) and
640	     * {@code postcode} while carrying a <em>different</em> telephone (compared by canonical E.164 form,
641	     * see {@link TelephoneNormalizer#canonicalize(String)}), or {@code null} when no such owner exists.
642	     * The check runs only after the exact-identity duplicate check ({@link #rejectDuplicateIdentity(Owner)})
643	     * has passed, so a shared last-name-and-postcode with the same telephone has already been rejected as
644	     * a hard duplicate and can never surface here. A blank {@code postcode} never matches, since two
645	     * owners without a postcode do not share one. The captured id is stored on the new owner and surfaced
646	     * as the read-only {@code possibleDuplicate} / {@code possibleDuplicateOf} fields.
647	     *
648	     * @param owner the fully-populated owner being created (telephone normalized)
649	     * @return the id of the first soft-matching existing owner, or {@code null} when none matches
650	     */
651	    private Integer possibleDuplicateOf(Owner owner) {
652	        if (owner.getPostcode() == null || owner.getPostcode().isBlank()) {
653	            return null;
654	        }
655	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
656	        return this.clinicService.findAllOwners().stream()
657	            .filter(existing -> equalsIgnoreCase(existing.getLastName(), owner.getLastName())
658	                && owner.getPostcode().equals(existing.getPostcode())
659	                && !java.util.Objects.equals(telephone, telephoneNormalizer.canonicalize(existing.getTelephone())))
660	            .map(Owner::getId)
661	            .filter(java.util.Objects::nonNull)
662	            .findFirst()
663	            .orElse(null);
664	    }
