666	    /**
667	     * Reduces an owner to its derived {@code identityKey}, formatted
668	     * {@code '<normalizedTelephone>|<email>|<householdId>'}: the owner's telephone reduced to its
669	     * canonical E.164 form (see {@link TelephoneNormalizer#canonicalize(String)}), the owner's
670	     * normalized (lower-cased) email or the empty string when absent (see
671	     * {@link EmailNormalizer#normalize(String)}), and the owner's {@code householdId} or the empty
672	     * string when absent, joined by {@code '|'}. Two owners are duplicates exactly when their whole
673	     * identity keys are equal. The key never contains {@code null} segments, so the create endpoint's
674	     * single duplicate check compares this one value across owners.
675	     *
676	     * @param owner the owner to derive the identity key for
677	     * @return the owner's identity key
678	     */
679	    private String identityKey(Owner owner) {
680	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
681	        String normalizedEmail = emailNormalizer.normalize(owner.getEmail());
682	        String email = normalizedEmail == null ? "" : normalizedEmail;
683	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
684	        return telephone + "|" + email + "|" + household;
685	    }
