687	    /**
688	     * Finds the first existing owner that already carries the given comparison {@code key}, derived
689	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null} are
690	     * ignored (a {@code null} key never equals the sought key). The create endpoint's duplicate
691	     * checks reduce both an existing owner and the owner being created to the same canonical key;
692	     * this returns the matched existing owner itself, so a caller can either reject the collision or
693	     * record which owner was matched.
694	     *
695	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
696	     * @param key the canonical key of the owner being created
697	     * @return the first existing owner sharing the key, or empty when none does
698	     */
699	    private Optional<Owner> findExistingOwner(Function<Owner, String> keyExtractor, String key) {
700	        return this.clinicService.findAllOwners().stream()
701	            .filter(owner -> key.equals(keyExtractor.apply(owner)))
702	            .findFirst();
703	    }
704	
705	    /**
706	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
707	     * from each owner by {@code keyExtractor} (see {@link #findExistingOwner(Function, String)}).
708	     * The create endpoint's duplicate checks use this to reduce both an existing owner and the owner
709	     * being created to the same canonical key and reject a match.
710	     *
711	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
712	     * @param key the canonical key of the owner being created
713	     * @return {@code true} if some existing owner shares the key
714	     */
715	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
716	        return findExistingOwner(keyExtractor, key).isPresent();
717	    }
718	
719	    /**
720	     * Counts the existing owners that satisfy the given {@code predicate}. The create endpoint's
721	     * count-based rules - the per-city capacity, the per-day create limit and the derived
722	     * {@code namesakeCount} - all accumulate owners over {@link ClinicService#findAllOwners()} and
723	     * differ only in the predicate they count by, so the scan-and-count is written in exactly one
724	     * place and each rule supplies just its own predicate.
725	     *
726	     * @param predicate the condition an owner must satisfy to be counted
727	     * @return the number of existing owners that satisfy the predicate
728	     */
729	    private long countOwners(Predicate<Owner> predicate) {
730	        return this.clinicService.findAllOwners().stream()
731	            .filter(predicate)
732	            .count();
733	    }
734	
735	    /**
736	     * Delimiter joining the canonical {@code lastName} and the {@code postcode} when deriving the
737	     * shared {@code householdId}.
738	     */
739	    private static final String HOUSEHOLD_KEY_DELIMITER = "|";
740	
741	    /**
742	     * Reduces the household {@code lastName} to a canonical form for case-insensitive,
743	     * whitespace-insensitive comparison: leading and trailing whitespace is trimmed, every run of
744	     * internal whitespace is collapsed to a single space, and the result is lower-cased using
745	     * {@link java.util.Locale#ROOT} so comparison is locale-independent.
746	     *
747	     * @param value the raw field value, or {@code null}
748	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
749	     */
750	    private String canonicalizeHousehold(String value) {
751	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
752	    }
753	
754	    /**
755	     * Derives the deterministic, shared {@code householdId} for an owner from its {@code lastName}
756	     * and {@code postcode}. The identifier is the first 12 upper-case hex characters of the SHA-256
757	     * hash of {@code normalizedLastName + '|' + postcode} (see {@link #canonicalizeHousehold(String)}
758	     * for the last-name normalization), so every owner with the same last name and postcode -
759	     * regardless of casing or spacing - is automatically assigned the identical value. Owners without
760	     * a postcode have no household basis and are given no household id ({@code null}).
761	     *
762	     * @param owner the owner being created
763	     * @return the shared household identifier, or {@code null} when the owner has no postcode
764	     */
765	    /**
766	     * Counts the owners in the given owner's household: the existing owners that share its
767	     * {@code householdId} (see {@link #householdId(Owner)}), which - because the owner being counted is
768	     * itself persisted before it is decorated - includes the owner. An owner with no {@code householdId}
769	     * (e.g. no postcode) has no shared household and counts as a household of one. The value feeds the
770	     * household factor of the owner's membership points.
771	     *
772	     * @param owner the owner whose household size is being derived
773	     * @return the number of owners in the owner's household (at least {@code 1})
774	     */
775	    private int householdSize(Owner owner) {
776	        String household = owner.getHouseholdId();
777	        if (household == null) {
778	            return 1;
779	        }
780	        return (int) countOwners(existing -> household.equals(existing.getHouseholdId()));
781	    }
782	
783	    private String householdId(Owner owner) {
784	        String postcode = owner.getPostcode();
785	        if (postcode == null || postcode.isBlank()) {
786	            return null;
787	        }
788	        String key = canonicalizeHousehold(owner.getLastName()) + HOUSEHOLD_KEY_DELIMITER + postcode;
789	        return hashPrefix(key, HOUSEHOLD_ID_LENGTH);
790	    }
791	
792	    /**
793	     * Number of leading hex characters of the household hash retained as the shared
794	     * {@code householdId}.
795	     */
796	    private static final int HOUSEHOLD_ID_LENGTH = 12;
797	
798	    /**
799	     * Computes the leading {@code length} upper-case hex characters of the SHA-256 digest of the
800	     * UTF-8 bytes of {@code input}. This is the shared hashing primitive behind the derived
801	     * identifiers that fingerprint owner fields - such as the household-scoped {@code householdId} -
802	     * so every such identifier is produced by the same algorithm and differs only in the value it
803	     * hashes and the number of hex characters it keeps.
804	     *
805	     * @param input the value to hash
806	     * @param length the number of leading hex characters to keep
807	     * @return the leading {@code length} upper-case hex characters of the SHA-256 digest
808	     */
809	    private String hashPrefix(String input, int length) {
810	        try {
811	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
812	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
813	            StringBuilder sb = new StringBuilder(digest.length * 2);
814	            for (byte b : digest) {
815	                sb.append(String.format("%02X", b));
816	            }
817	            return sb.substring(0, length);
818	        } catch (java.security.NoSuchAlgorithmException e) {
819	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
820	        }
821	    }
822	}
