15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials", expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
24	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
25	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
26	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
27	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
28	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
29	    @Mapping(target = "locality", expression = "java(locality(owner))")
30	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
31	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
32	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
33	    @Mapping(target = "bulkSignupWarning", ignore = true)
34	    @Mapping(target = "identityKey", ignore = true)
35	    @Mapping(target = "possibleDuplicate", ignore = true)
36	    @Mapping(target = "possibleDuplicateOf", ignore = true)
37	    OwnerDto toOwnerDto(Owner owner);
38	
39	    /**
40	     * Derives the owner's {@code contactPreference} from the owner's own fields:
41	     * {@code EMAIL} when an email is present, otherwise {@code PHONE}.
42	     *
43	     * @param owner the owner being mapped
44	     * @return the derived contact preference
45	     */
46	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
47	        return hasEmail(owner) ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
48	    }
49	
50	    /**
51	     * Reports whether the owner has a usable {@code email}: present and not blank (whitespace-only).
52	     * The presence of an email drives several derived fields (such as the {@code contactPreference}
53	     * and the {@code membershipLevel}), so the "has an email" test is written in exactly one place
54	     * rather than repeated at each use.
55	     *
56	     * @param owner the owner being mapped
57	     * @return {@code true} when the owner has a non-blank email
58	     */
59	    default boolean hasEmail(Owner owner) {
60	        return owner.getEmail() != null && !owner.getEmail().isBlank();
61	    }
62	
63	    /**
64	     * Derives the owner's {@code ageBand} from its {@code birthDate}, measured against the owner's
65	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} for 18 to 64, and
66	     * {@code SENIOR} for 65 and over. Returns {@code null} when no birth date is present, in which
67	     * case the field is absent from the response. The age in whole years is the number of complete
68	     * years between the birth date and the registration date (see {@link java.time.Period}); when the
69	     * registration date is somehow absent the current date is used as the reference.
70	     *
71	     * @param owner the owner being mapped
72	     * @return the derived age band, or {@code null} when no birth date is present
73	     */
74	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
75	        java.time.LocalDate birthDate = owner.getBirthDate();
76	        if (birthDate == null) {
77	            return null;
