163	     */
164	    default Integer membershipLevel(Owner owner) {
165	        int points = membershipPoints(owner);
166	        if (points <= 1) {
167	            return 1;
168	        }
169	        if (points <= 3) {
170	            return 2;
171	        }
172	        if (points <= 5) {
