202	     */
203	    default String membershipNumber(Owner owner) {
204	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
205	            return null;
206	        }
207	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
208	    }
