210	    /**
211	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits
212	     * contained in the {@code customerCode} (non-digit characters, such as the {@code '<REGION>-'}
213	     * prefix, the separator and the hex letters {@code A-F}, are ignored). Returns {@code null} when
214	     * the customer code is absent.
215	     *
216	     * @param owner the owner being mapped
217	     * @return the Luhn check digit, or {@code null} when no customer code is present
218	     */
219	    default Integer checkDigit(Owner owner) {
220	        String code = owner.getCustomerCode();
221	        if (code == null) {
222	            return null;
223	        }
224	        int sum = 0;
225	        boolean dbl = true;
226	        for (int i = code.length() - 1; i >= 0; i--) {
227	            char c = code.charAt(i);
228	            if (c < '0' || c > '9') {
229	                continue;
230	            }
231	            int d = c - '0';
232	            if (dbl) {
233	                d *= 2;
234	                if (d > 9) {
